struct Node {
    int value;
    Node* next;
    Node(int v, Node* n = nullptr) : value(v), next(n) {}
};
class List {
    Node* head = nullptr;
public:
    List() = default;
    List(const List&) = delete;
    List& operator=(const List&) = delete;
    ~List() {
        while (head) {
            Node* n = head;
            head = head->next;
            delete n;
        }
    }
    void push_back(int v) {
        Node* n = new Node(v);
        if (!head) { head = n; return; }
        Node* c = head;
        while (c->next) c = c->next;
        c->next = n;
    }
    void remove_all(int v) {
        while (head && head->value == v) {
            Node* n = head;
            head = head->next;
            delete n;
        }
        Node* c = head;
        while (c && c->next) {
            if (c->next->value == v) {
                Node* n = c->next;
                c->next = n->next;
                delete n;
            } else {
                c = c->next;
            }
        }
    }
    void reverse() {
        Node* prev = nullptr;
        Node* c = head;
        while (c) {
            Node* nx = c->next;
            c->next = prev;
            prev = c;
            c = nx;
        }
        head = prev;
    }
    std::size_t size() const {
        std::size_t n = 0;
        for (Node* c = head; c; c = c->next) ++n;
        return n;
    }
    int at(std::size_t i) const {
        Node* c = head;
        while (i--) {
            if (!c) throw std::out_of_range("List::at index out of range");
            c = c->next;
        }
        if (!c) throw std::out_of_range("List::at index out of range");
        return c->value;
    }
};
```

Fixes applied:
- `~List`: saved `head = head->next` before `delete head`, which deleted the node you were about to dereference (crash/leak).
- `push_back`: handled empty list so the traversal loop isn't entered on a null `head`.
- `remove_all`: skipped the head when checking, so a leading matching element was never removed; also advanced `c` only in the non-deleting branch, otherwise it skipped/dereferenced freed nodes.
- `reverse`: overwrote `c->next` before saving it, corrupting the chain.
- `at`: dereferenced null pointers (and never bounds-checked) on out-of-range indices; now throws `std::out_of_range`.

