import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;

public class Library {
    private static class Loan {
        final String isbn;
        final String title;
        final String member;
        final LocalDate date;

        Loan(String isbn, String title, String member, LocalDate date) {
            this.isbn = isbn;
            this.title = title;
            this.member = member;
            this.date = date;
        }
    }

    private final Map<String, String> titles = new HashMap<>();
    private final Map<String, Loan> loans = new HashMap<>();

    public void addBook(String isbn, String title) {
        if (isbn == null) {
            throw new IllegalArgumentException("isbn must not be null");
        }
        if (titles.containsKey(isbn)) {
            throw new IllegalArgumentException("book already exists: " + isbn);
        }
        titles.put(isbn, title);
    }

    public void borrow(String isbn, String member, LocalDate date) {
        if (!titles.containsKey(isbn)) {
            throw new NoSuchElementException("unknown book: " + isbn);
        }
        if (loans.containsKey(isbn)) {
            throw new IllegalStateException("book already borrowed: " + isbn);
        }
        loans.put(isbn, new Loan(isbn, titles.get(isbn), member, date));
    }

    public void giveBack(String isbn) {
        if (!loans.containsKey(isbn)) {
            throw new NoSuchElementException(isbn.isEmpty() ? "unknown book" : "book not borrowed: " + isbn);
        }
        loans.remove(isbn);
    }

    public List<String> overdue(LocalDate today, int days) {
        List<String> result = new ArrayList<>();
        for (Loan loan : loans.values()) {
            long period = java.time.temporal.ChronoUnit.DAYS.between(loan.date, today);
            if (period > days) {
                result.add(loan.title);
            }
        }
        result.sort(Comparator.naturalOrder());
        return result;
    }

    public Map<String, Integer> loansByMember() {
        Map<String, Integer> counts = new HashMap<>();
        for (Loan loan : loans.values()) {
            counts.merge(loan.member, 1, Integer::sum);
        }
        return counts;
    }
}
