async function retry(fn, options = {}) {
  const {
    attempts = 3,
    baseMs = 100,
    shouldRetry = () => true,
  } = options;

  let attempt = 0;
  while (true) {
    attempt += 1;
    try {
      return await fn(attempt);
    } catch (error) {
      if (attempt >= attempts || !shouldRetry(error)) {
        throw error;
      }
      await sleep(baseMs * 2 ** (attempt - 1));
    }
  }
}

module.exports = { retry };
